const fs = require('fs');
const initSqlJs = require('/home/node/.n8n/nodes/node_modules/sql.js');
const DB_PATH = '/home/node/.n8n/assistant.db';
const SQL = await initSqlJs();
const db = new SQL.Database(fs.readFileSync(DB_PATH));
const created = db.exec("SELECT title, priority FROM tasks WHERE DATE(created_at) = DATE('now', 'localtime')");
const completed = db.exec("SELECT title FROM tasks WHERE status='done' AND DATE(created_at) = DATE('now', 'localtime')");
const pending = db.exec("SELECT title, priority FROM tasks WHERE status='pending' ORDER BY priority LIMIT 5");
const msgs = db.exec("SELECT content FROM messages WHERE DATE(timestamp) = DATE('now', 'localtime') LIMIT 20");
let expenses = [];
try { const r = db.exec("SELECT amount, category, description FROM expenses WHERE DATE(logged_at) = DATE('now', 'localtime')"); expenses = r[0]?.values.map(row => ({amount: row[0], category: row[1], desc: row[2]})) || []; } catch(e) {}
let habitsToday = [];
try { const r = db.exec("SELECT h.name, he.completed, he.value FROM habit_entries he JOIN habits h ON h.id = he.habit_id WHERE he.date = date('now')"); habitsToday = r[0]?.values.map(row => ({name: row[0], done: row[1], value: row[2]})) || []; } catch(e) {}
let moodToday = null;
try { const r = db.exec("SELECT mood, energy_level FROM mood_entries WHERE DATE(logged_at) = DATE('now') ORDER BY logged_at DESC LIMIT 1"); if (r[0]?.values.length) moodToday = {mood: r[0].values[0][0], energy: r[0].values[0][1]}; } catch(e) {}
let commitments = [];
try { const r = db.exec("SELECT description, deadline FROM commitments WHERE status = 'active' ORDER BY deadline ASC LIMIT 5"); commitments = r[0]?.values.map(row => ({desc: row[0], deadline: row[1]})) || []; } catch(e) {}
let recentTopics = [];
try { const r = db.exec("SELECT topic, summary FROM active_topics WHERE status = 'open' ORDER BY last_mentioned DESC LIMIT 3"); recentTopics = r[0]?.values.map(row => ({topic: row[0], summary: row[1]})) || []; } catch(e) {}
let projects = [];
try { const r = db.exec("SELECT name, last_updated FROM projects WHERE status = 'active'"); projects = r[0]?.values.map(row => ({name: row[0], updated: row[1]})) || []; } catch(e) {}
db.close();
const triggerInput = $input.first().json;
const checkinText = triggerInput.args || triggerInput.text || triggerInput.checkin_text || '';
return [{ json: { created_today: created[0]?.values.map(r => ({title: r[0], priority: r[1]})) || [], completed_today: completed[0]?.values.map(r => r[0]) || [], pending: pending[0]?.values.map(r => ({title: r[0], priority: r[1]})) || [], messages_today: msgs[0]?.values.map(r => r[0]) || [], expenses_today: expenses, habits_today: habitsToday, mood_today: moodToday, commitments: commitments, recent_topics: recentTopics, projects: projects, chat_id: triggerInput.chat_id || $env.TELEGRAM_CHAT_ID, checkin_text: checkinText, has_answers: checkinText.trim().length > 0, date: new Date().toLocaleDateString('en-KE', {weekday: 'long', month: 'short', day: 'numeric', timeZone: 'Africa/Nairobi'}) } }];

