const data = $input.first().json;
const text = data.checkin_text || '';
const moodKeywords = { great: ['amazing', 'great', 'excellent', 'productive', 'crushed'], good: ['good', 'solid', 'decent', 'fine', 'alright'], okay: ['meh', 'average', 'normal', 'so-so'], low: ['tired', 'exhausted', 'drained', 'unproductive', 'rough'], bad: ['terrible', 'awful', 'failed', 'wasted', 'nothing'] };
const lower = text.toLowerCase();
let mood = 'okay';
for (const [level, keywords] of Object.entries(moodKeywords)) { if (keywords.some(k => lower.includes(k))) { mood = level; break; } }
let energy = null;
const energyMatch = text.match(/energy[\s:]*([1-5])/i);
if (energyMatch) energy = parseInt(energyMatch[1]);
return [{ json: { ...data, reflection_text: text, mood, energy } }];

