const fs = require('fs');
const initSqlJs = require('/home/node/.n8n/nodes/node_modules/sql.js');
const DB_PATH = '/home/node/.n8n/assistant.db';
const data = $input.first().json;
const SQL = await initSqlJs();
const db = new SQL.Database(fs.readFileSync(DB_PATH));
const date = new Date().toISOString().split('T')[0];
db.run("INSERT OR REPLACE INTO reflections (date, q1_accomplished, q2_time_usage, q3_pending, q4_blockers, summary, mood_signal) VALUES (?, ?, ?, ?, ?, ?, ?)", [date, data.completed_today?.join(', ') || '', data.reflection_text || '', data.pending?.map(t=>t.title).join(', ') || '', '', data.summary || '', data.mood || 'unclear']);
try { db.run("INSERT INTO mood_entries (mood, energy_level, notes, source) VALUES (?, ?, ?, 'checkin')", [data.mood || 'okay', data.energy || null, data.reflection_text || '']); } catch(e) {}
try { const topics = (data.recent_topics || []).map(t => t.topic); db.run("INSERT INTO conversation_summaries (session_id, started_at, ended_at, summary, topics, mood, message_count) VALUES (?, datetime('now', '-2 hours'), datetime('now'), ?, ?, ?, ?)", ['evening-' + date, data.summary || '', JSON.stringify(topics), data.mood || 'okay', data.messages_today?.length || 0]); } catch(e) {}
fs.writeFileSync(DB_PATH + '.tmp', Buffer.from(db.export())); fs.renameSync(DB_PATH + '.tmp', DB_PATH);
db.close();
return [{ json: { ...data, date } }];
